if (!model.activityCode || model.activityCode.length === 0 || !model.activityWasCancelled || model.activityWasCancelled.length === 0) {
  return false;
}
let newActivityCodes = model.activityCode.map(it => {
  const code = it.code;
  const index = code.indexOf('.');
  return index === -1 ? code : code.substring(0, index);
});
newActivityCodes = [...new Set(newActivityCodes)];
return model.activityWasCancelled
  .map(it => it.code)
  .some(oldCode => newActivityCodes.some(newCode => oldCode.startsWith(newCode + '.') || oldCode === newCode));

